import{_ as a,c as i,o as t,ag as n}from"./chunks/framework.Bw-5EFTY.js";const d=JSON.parse('{"title":"Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/integrations.md","filePath":"guide/integrations/integrations.md","lastUpdated":1756182610000}'),r={name:"guide/integrations/integrations.md"};function o(s,e,l,g,f,m){return t(),i("div",null,e[0]||(e[0]=[n('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><p>FluentAffiliate seamlessly integrates with many popular WordPress plugins to help you manage affiliate marketing across your entire digital business. Whether you&#39;re selling products, courses, or services, our integrations make it easy to track and reward affiliate referrals.</p><h2 id="available-integrations" tabindex="-1">Available Integrations <a class="header-anchor" href="#available-integrations" aria-label="Permalink to &quot;Available Integrations&quot;">​</a></h2><p>FluentAffiliate offers plug-and-play integration with the following platforms:</p><h3 id="e-commerce" tabindex="-1">E-Commerce <a class="header-anchor" href="#e-commerce" aria-label="Permalink to &quot;E-Commerce&quot;">​</a></h3><p>Running an online store? FluentAffiliate integrates perfectly with popular e-commerce platforms:</p><ul><li><strong><a href="/guide/integrations/woocommerce-integration-with-fluentaffiliate">WooCommerce Integration</a></strong> - Track affiliate referrals for your WooCommerce store purchases. Perfect for physical and digital products alike.</li><li><strong><a href="/guide/integrations/easy-digital-downloads-integration-with-fluentaffiliate">Easy Digital Downloads</a></strong> - Monitor affiliate sales for your digital products with detailed commission tracking.</li><li><strong><a href="/guide/integrations/surecart-integration-with-fluentaffiliate">SureCart</a></strong> - Handle affiliate marketing for your SureCart store with automated commission calculations.</li></ul><h3 id="learning-management-systems-lms" tabindex="-1">Learning Management Systems (LMS) <a class="header-anchor" href="#learning-management-systems-lms" aria-label="Permalink to &quot;Learning Management Systems (LMS)&quot;">​</a></h3><p>Selling courses or memberships? Our LMS integrations have you covered:</p><ul><li><strong><a href="/guide/integrations/lifterlms-integration-with-fluentaffiliate">LifterLMS</a></strong> - Track affiliate referrals for course sales with customizable commission structures.</li><li><strong><a href="/guide/integrations/memberpress-integration-with-fluentaffiliate">MemberPress</a></strong> - Monitor affiliate commissions for membership signups and recurring payments.</li><li><strong><a href="/guide/integrations/paid-memberships-pro-integration-with-fluentaffiliate">Paid Memberships Pro</a></strong> - Monitor affiliate commissions for membership signups.</li></ul><h3 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h3><p>Need to track form submissions or manage your affiliate relationships?</p><ul><li><strong><a href="/guide/integrations/fluentforms-integration-with-fluentaffiliate">Fluent Forms</a></strong> - Generate commissions from form submissions and track conversion rates.</li></ul><h3 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h3><p>Need to track donation or payment? Our Payment integrations have you covered:</p><ul><li><strong><a href="/guide/integrations/givewp-integration-with-fluentaffiliate">GiveWP</a></strong> - Allow affiliates to earn commissions by promoting your donation campaigns.</li><li><strong><a href="/guide/integrations/paymattic-integration-with-fluentaffiliate">Paymattic</a></strong> - Track affiliate commissions for payments and donations made through Paymattic forms.</li></ul><h3 id="booking-and-appointments" tabindex="-1">Booking and Appointments <a class="header-anchor" href="#booking-and-appointments" aria-label="Permalink to &quot;Booking and Appointments&quot;">​</a></h3><ul><li><strong><a href="/guide/integrations/fluentbooking-integration-with-fluentaffiliate">Fluent Booking</a></strong> - Track affiliate referrals for booking services and appointments.</li></ul><p>Each integration works seamlessly with FluentAffiliate, allowing you to:</p><ul><li>Track referrals automatically through our <a href="/guide/admin-portal/managing-referrals">referral tracking system</a></li><li>Set specific commission rates per product or service in <a href="/guide/settings-and-customization/referral-settings">referral settings</a></li><li>Monitor affiliate performance across different platforms in your <a href="/guide/admin-portal/admin-dashboard-overview">admin dashboard</a></li><li>Generate accurate <a href="/guide/admin-portal/payout-management">payouts</a> based on verified sales</li></ul><h2 id="setting-up-integrations" tabindex="-1">Setting Up Integrations <a class="header-anchor" href="#setting-up-integrations" aria-label="Permalink to &quot;Setting Up Integrations&quot;">​</a></h2><p>To enable any integration:</p><ol><li>Navigate to <strong>Settings</strong> in your FluentAffiliate dashboard</li><li>Click on <strong>Integration Settings</strong></li><li>Find the integration you want to enable</li><li>Toggle it on and configure any specific settings</li></ol><p>Each integration can be customized with its own commission rates, rules, and settings. You can also set up <a href="/guide/settings-and-customization/group-settings">affiliate groups</a> to manage different commission structures for different types of affiliates.</p><p>Need to manage affiliates across multiple sites? Check out our <a href="/guide/settings-and-customization/multi-domain-management">multi-domain management</a> feature.</p>',25)]))}const c=a(r,[["render",o]]);export{d as __pageData,c as default};
